  ['certificate-parsing', ['parseDer']],
  ['tls-key-schedule-and-finished', ['handshakeKeys', 'applicationKeys', 'trafficKeys', 'expandLabel', 'hmac', 'verifyFinished', 'finishedVerifyData', 'hash']],
  ['client-hello', ['createClientHello']],
  ['buffer-helpers', ['concat', 'bytes', 'take', 'vector', 'extension', 'handshake', 'record']],
  ['other-tls-and-probe', ['probeWithConnect', 'push', 'serverHello', 'certificate', 'certificateVerify', 'serverFinished', 'finishHandshake', 'readiness', 'dispose', 'parseEchConfigList']],
