});
const aggregateProfiles = [...totals.values()].map(t => ({ mode: t.mode, samples: t.samples, activeStackObservations: t.activeStackObservations,
  disjointGroupStackCounts: Object.fromEntries(t.groups),
  topSelfStackCounts: [...t.self].sort((a,b) => b[1]-a[1]).slice(0, 20).map(([name,samples]) => ({name,samples})),
  inclusiveStackCounts: Object.fromEntries(t.inclusive),
