const batchSummaries = [...new Set(measurements.batches.map(row => row.mode))].map(mode => {
  const rows = measurements.batches.filter(row => row.mode === mode);
  const count = rows.reduce((n,row)=>n+row.count,0), processCpuMs = rows.reduce((n,row)=>n+row.processCpuMs,0);
