  profilingMethod: { requestedSamplingIntervalUs: 100, grouping: 'Disjoint priority match on synchronous stack ancestry; unknown/program samples remain unknown', inclusiveStackCountsOverlap: true, samplingGapsAreNotCpu: true, percentagesAreNotCpuShares: true, nativeCryptoCpuNotFullyAttributed: true },
};
